from (values
('P1 Map Landmark Recall','positioning','beginner',array['P1 Primary Rusher'],10,'Build fast, consistent landmark identification before reporting a location.','Use six labeled map landmarks and a blank map.',array['Name each landmark from memory','Point to two nearby references','Describe the direction between them','Compare with the squad glossary'],'At least five of six landmarks are identified consistently.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p1','role-engine','progression']),
('P1 Clear Status Call','communication','beginner',array['P1 Primary Rusher'],10,'Give a concise status update that teammates can understand immediately.','Use scripted map checkpoints and a callout timer.',array['State current landmark','State current status','State next checkpoint','Ask for acknowledgement only when needed'],'Four consecutive updates contain all required information.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p1','role-engine','progression']),
('P1 Route Brief and Repeatback','rotation','medium',array['P1 Primary Rusher'],15,'Explain a planned route and verify shared understanding before moving.','Use a map with three checkpoints and one fallback.',array['Name destination','List checkpoints in order','State regroup point','Ask one teammate to repeat the plan'],'Teammate repeats the same route and fallback without prompts.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p1','role-engine','progression']),
('P1 Uncertainty Reporting','communication','medium',array['P1 Primary Rusher'],15,'Separate confirmed observations from assumptions when reporting.','Coach provides mixed confirmed and uncertain map facts.',array['Label confirmed facts','Label unknowns','Report only decision-relevant details','Update when evidence changes'],'No uncertain detail is presented as confirmed.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p1','role-engine','progression']),
('P1 Plan Change Explanation','role','advanced',array['P1 Primary Rusher'],20,'Explain when new information invalidates the agreed plan.','Pause a replay before and after a map-state change.',array['State the old assumption','Identify new verified information','Explain the impact','Request a revised call','Repeat the new checkpoint'],'The squad can explain why the plan changed and what replaces it.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p1','role-engine','progression']),
('P1 Tempo and Pause Discipline','communication','advanced',array['P1 Primary Rusher'],15,'Avoid rushing ahead of the squad''s shared checkpoint and readiness.','Run a non-combat route walkthrough with timed pause signals.',array['Confirm current checkpoint','Wait for readiness replies','Report delay clearly','Resume only after shared confirmation'],'No player is left acting on an outdated checkpoint.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p1','role-engine','progression']),
('P1 Multi-Source Information Merge','communication','elite',array['P1 Primary Rusher'],20,'Combine separate teammate observations into one accurate summary.','Three teammates receive different map observation cards.',array['Listen to each report','Remove duplicate facts','Flag contradictions','Summarize verified picture','Ask for one missing verification'],'Summary preserves all critical facts and clearly marks uncertainty.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p1','role-engine','progression']),
('P1 Pressure Communication Review','review','elite',array['P1 Primary Rusher'],20,'Maintain clear communication during a fast-changing simulated map scenario.','Use a replay with frequent pauses and a callout log.',array['Give one concise update per meaningful change','Avoid repeated unchanged calls','Record missed acknowledgements','Review timestamps','Set one measurable correction'],'Callout log shows fewer duplicate or late updates on the second attempt.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p1','role-engine','progression']),
('P2 Instruction Repeatback','communication','beginner',array['P2 Secondary Rusher'],10,'Confirm instructions accurately rather than relying on assumptions.','Coach gives six short route and checkpoint instructions.',array['Listen fully','Repeat action and destination','Ask one clarification','Confirm completion'],'All six instructions are repeated and completed correctly.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p2','role-engine','progression']),
