('P3 Early Change Notification','rotation','advanced',array['P3 Third Rusher / Flanker'],20,'Notify the IGL early when a verified map change affects the planned route.','Use a staged map-state timeline.',array['Track current checkpoint','Spot relevant change','Report source and landmark','Explain route impact','Confirm revised checkpoint'],'Relevant change is reported before the team reaches the affected checkpoint.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p3','role-engine','progression']),
